import ts from '/home/user/exp0007-arm/node_modules/typescript/lib/typescript.js';

const root = '/home/user/exp0007-arm';
const configPath = ts.findConfigFile(root, ts.sys.fileExists, 'tsconfig.json');
if (!configPath) {
  console.error('NO_TSCONFIG');
  process.exit(2);
}

const parsed = ts.getParsedCommandLineOfConfigFile(configPath, { noEmit: true }, {
  ...ts.sys,
  onUnRecoverableConfigFileDiagnostic: (d) =>
    console.error('CONFIG_ERROR', ts.flattenDiagnosticMessageText(d.messageText, ' ')),
});

const program = ts.createProgram({
  rootNames: parsed.fileNames,
  options: { ...parsed.options, noEmit: true },
  projectReferences: parsed.projectReferences,
});

const diags = ts.getPreEmitDiagnostics(program);
let printed = 0;
for (const d of diags) {
  const msg = ts.flattenDiagnosticMessageText(d.messageText, ' ');
  if (d.file) {
    const { line, character } = d.file.getLineAndCharacterOfPosition(d.start);
    const rel = d.file.fileName.startsWith(root + '/') ? d.file.fileName.slice(root.length + 1) : d.file.fileName;
    console.log(`${rel}(${line + 1},${character + 1}): error TS${d.code}: ${msg}`);
  } else {
    console.log(`error TS${d.code}: ${msg}`);
  }
  printed++;
}
console.log(`TOTAL_ERRORS=${printed}`);
const target = diags.filter((d) => d.file && d.file.fileName.includes('server/services/auto-apply-pipeline.ts'));
console.log(`AUTO_APPLY_PIPELINE_ERRORS=${target.length}`);

